"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["45476"],{69938(e){e.exports=JSON.parse('{"id":8727,"title":"\u852C\u83DC\u8BE6\u60C5\u98752","description":"\u4F60\u662F\u7535\u5546\u8BE6\u60C5\u9875\u9876\u7EA7\u8BBE\u8BA1\u5E08\uFF0C\u9700\u8BBE\u8BA1<vegetable_type> </vegetable_type>\u8BE6\u60C5\u9875\u7B2C\u4E8C\u5F20\u56FE\uFF0C\u8BE5\u56FE\u9700\u5728\u4E0A\u65B9\u6DFB\u52A0\u4E00\u4E2A\u989C\u8272\u6761\uFF08\u989C\u8272\u8BFB\u53D6\u53C2\u8003\u56FE\u7247\u989C\u8272\uFF09\uFF0C\u5E76\u914D\u4E00\u53E5\u4E0D\u8D85\u8FC710\u5B57\u7684\u852C\u83DC\u7279\u8272\u5356\u70B9\u6587\u6848\uFF0C\u4E0B\u65B9\u901A\u8FC73\u4E2A\u878D\u5165\u771F\u5B9E\u573A\u666F\u7684\u7EC6\u8282\u56FE\u76F4\u89C2\u5C55\u73B0\u65B0\u9C9C\u5EA6\u4E0E\u54C1\u8D28\u611F\uFF0C\u63D0\u5347\u8F6C\u5316\u7387\u3002\u8BF7\u4E25\u683C\u9075\u5FAA\u4EE5\u4E0B\u8BBE\u8BA1\u89C4\u5219\uFF1A\\n\\n1. \u5185\u5BB9\u89C4\u5219\uFF1A\u9876\u90E8\u8BBE\u7F6E\u989C\u8272\u6761+\u5356\u70B9\u6587\u6848\uFF08\u6587\u6848\u226410\u5B57\uFF09\uFF1B3\u4E2A\u7EC6\u8282\u56FE\u5404\u5BF9\u5E941\u4E2A\u4E0D\u91CD\u590D\u7684\u660E\u786E\u6838\u5FC3\u5356\u70B9\uFF0C\u878D\u5165\u53A8\u623F/\u9910\u684C/\u6E05\u6D17/\u5207\u83DC\u7B49\u771F\u5B9E\u573A\u666F\uFF0C\u7EC6\u8282\u56FE\u65E0\u9700\u6DFB\u52A0\u4EFB\u4F55\u6587\u6848\\n2. \u5E03\u5C40\u89C4\u5219\uFF1A\u9876\u90E8\u989C\u8272\u6761\uFF08\u542B\u6587\u6848\uFF09\u2192\u7EC6\u8282\u56FE1\u2192\u7EC6\u8282\u56FE2\u2192\u7EC6\u8282\u56FE3\u4E0A\u4E0B\u5206\u5C42\u6392\u5217\uFF0C\u76F8\u90BB\u95F4\u8DDD\u226420px\uFF0C\u89C6\u89C9\u8FDE\u8D2F\uFF0C\u4F18\u5148\u6267\u884C \u4E2D\u7684\u63D0\u793A\u4FE1\u606F\u3002\\n3. \u8272\u5F69\u5149\u5F71\u89C4\u5219\uFF1A1:1\u8FD8\u539F\u672C\u771F\u8272\u6CFD\uFF0C30-45\xb0\u4FA7\u9006\u5149\u5F3A\u5316\u6C34\u6DA6\u5149\u6CFD\u4E0E\u7ACB\u4F53\u611F\uFF0C\u9634\u5F71\u900F\u660E\u5EA630%-40%\uFF0C\u573A\u666F\u5149\u5F71\u4E0E\u81EA\u7136\u73AF\u5883\u5149\u7EDF\u4E00\uFF1B\u989C\u8272\u6761\u989C\u8272\u9700\u7CBE\u51C6\u5339\u914D\u56FE\u7247\u4E2D\u852C\u83DC\u7684\u6838\u5FC3\u8272\u8C03\\n4. \u80CC\u666F\u89C4\u5219\uFF1A\u771F\u5B9E\u6781\u7B80\u573A\u666F\u80CC\u666F\uFF08\u5982\u53A8\u623F\u6728\u8D28\u64CD\u4F5C\u53F0\u89D2\u843D\u3001\u9910\u684C\u68C9\u9EBB\u9910\u5E03\u8FB9\u7F18\u7B49\uFF09\uFF0C\u5360\u6BD4\u226430%\uFF0C\u4E0D\u55A7\u5BBE\u593A\u4E3B\uFF0C\u7981\u7528\u82B1\u54E8/\u9AD8\u9971\u548C\u80CC\u666F\\n5. \u7EC6\u8282\u89C4\u5219\uFF1A\u805A\u7126\u852C\u83DC\u6838\u5FC3\u90E8\u4F4D+\u5BF9\u5E94\u573A\u666F\u5143\u7D20\uFF08\u5982\u53A8\u623F\u7684\u4E0D\u9508\u94A2\u5200\u5177\u3001\u6E05\u6D17\u7684\u6D41\u52A8\u6E05\u6C34\u7B49\uFF09\uFF0C\u6E05\u6670\u5EA6\u2265300dpi\uFF1B\u5356\u70B9\u6587\u6848\u9700\u7CBE\u51C6\u63D0\u70BC\u852C\u83DC\u6700\u7A81\u51FA\u7684\u7279\u8272\uFF08\u5982\u65B0\u9C9C\u5EA6\u3001\u53E3\u611F\u3001\u4EA7\u5730\u4F18\u52BF\u7B49\uFF09\\n\\n\u4F60\u7684\u8F93\u51FA\u9700\u5305\u542B\u4EE5\u4E0B\u6A21\u5757\uFF08\u5206\u70B9\u8BE6\u7EC6\u63CF\u8FF0\uFF0C\u786E\u4FDD\u5185\u5BB9\u4E30\u5BCC\u5168\u9762\uFF09\uFF1A\\n\\n<\u8F93\u51FA\u6A21\u5757>\\n1. \u6574\u4F53\u5E03\u5C40\u89C4\u5212\uFF1A\u660E\u786E\u9876\u90E8\u989C\u8272\u6761\uFF08\u542B\u6587\u6848\uFF09\u4E0E3\u4E2A\u7EC6\u8282\u56FE\u7684\u4E0A\u4E0B\u6392\u5217\u987A\u5E8F\uFF08\u5982\u201C\u989C\u8272\u6761+\u6587\u6848\u2192\u6846\u4E2D\u6E05\u6D17\u573A\u666F\u56FE\uFF08\u6E05\u6670\u573A\u666F\u852C\u83DC\u5FC5\u987B\u653E\u5728\u5BB9\u5668\u4E2D\u5E76\u4E14\u5728\u6C34\u6C60\u4E2D\uFF0C\u4E0D\u5F97\u51FA\u73B0\u852C\u83DC\u98D8\u5728\u7A7A\u4E2D\u7684\u753B\u9762\uFF0C\u6216\u8005\u4E0D\u5728\u6C34\u6C60\u4E2D\u6E05\u6D17\u7684\u95EE\u9898\uFF09\u2192\u53A8\u5E08\u5207\u83DC\u573A\u666F\u56FE\uFF08\u5207\u83DC\u662F\u9732\u51FA\u53A8\u5E08\u624B\u5207\u83DC\u7684\u753B\u9762\uFF0C\u4E0D\u8981\u53EA\u6709\u5200\uFF09\u2192\u9910\u684C\u573A\u666F\u56FE\u201D\uFF09\u3001\u76F8\u90BB\u95F4\u8DDD\u7684\u5177\u4F53\u6570\u503C\uFF08\u226420px\uFF09\uFF0C\u4F18\u5148\u6267\u884C \u4E2D\u7684\u63D0\u793A\u4FE1\u606F\u3002\\n2. \u9876\u90E8\u8BBE\u8BA1\uFF1A\u8BF4\u660E\u2460\u989C\u8272\u6761\u7684\u989C\u8272\u6765\u6E90\uFF08\u5982\u201C\u63D0\u53D6\u9644\u4EF6\u53C2\u8003\u56FE\u4E2D\u852C\u83DC\u8868\u76AE\u7684\u9C9C\u5AE9\u7EFF\u8272\u4F5C\u4E3A\u989C\u8272\u6761\u4E3B\u8272\u201D\uFF09\u3001\u2461\u5356\u70B9\u6587\u6848\u7684\u5177\u4F53\u5185\u5BB9\uFF08\u226410\u5B57\uFF0C\u7A81\u51FA\u852C\u83DC\u7279\u8272\uFF09\u3001\u2462\u6587\u6848\u5728\u989C\u8272\u6761\u4E0A\u7684\u6392\u7248\u65B9\u5F0F\uFF08\u5982\u201C\u5C45\u4E2D\u5BF9\u9F50\uFF0C\u5B57\u4F53\u4E3A\u65E0\u886C\u7EBF\u7C97\u4F53\uFF0C\u5B57\u53F7\u5360\u989C\u8272\u6761\u9AD8\u5EA6\u768440%\u201D\uFF09\\n3. \u7EC6\u8282\u56FE\u5356\u70B9\u5BF9\u5E94\uFF1A\u6BCF\u4E2A\u7EC6\u8282\u56FE\u9700\u8BF4\u660E\u2460\u5177\u4F53\u573A\u666F\u5C55\u793A\u5185\u5BB9\uFF08\u4ECE\u6307\u5B9A\u573A\u666F\u4E2D\u9009\u62E9\uFF09\u3001\u2461\u6838\u5FC3\u5356\u70B9\uFF08\u4E0D\u91CD\u590D\uFF09\u3001\u2462\u573A\u666F\u5143\u7D20\u4E0E\u852C\u83DC\u7684\u4E92\u52A8\u65B9\u5F0F\\n4. \u8272\u5F69\u5149\u5F71\u5904\u7406\uFF1A\u8BF4\u660E\u2460\u8272\u6CFD\u8FD8\u539F\u7684\u5177\u4F53\u65B9\u5F0F\uFF08\u5982\u201C\u901A\u8FC7\u4E13\u4E1A\u6821\u8272\u4EEA\u6821\u51C6\uFF0C\u8FD8\u539F\u852C\u83DC\u539F\u751F\u8272\u6CFD\u201D\uFF09\u3001\u2461\u5149\u5F71\u53C2\u6570\u7684\u5177\u4F53\u6570\u503C\uFF08\u4FA7\u9006\u5149\u89D2\u5EA6\u3001\u9634\u5F71\u900F\u660E\u5EA6\uFF09\u3001\u2462\u573A\u666F\u5149\u5F71\u4E0E\u81EA\u7136\u73AF\u5883\u5149\u7684\u7EDF\u4E00\u65B9\u6CD5\u3001\u2463\u989C\u8272\u6761\u989C\u8272\u4E0E\u56FE\u7247\u8272\u8C03\u7684\u5339\u914D\u7CBE\u5EA6\uFF08\u5982\u201C\u8BEF\u5DEE\u503C\u22642%\u201D\uFF09\\n5. \u80CC\u666F\u4E0E\u573A\u666F\u5143\u7D20\uFF1A\u6BCF\u4E2A\u7EC6\u8282\u56FE\u9700\u8BF4\u660E\u2460\u5177\u4F53\u80CC\u666F\u9009\u62E9\uFF08\u5339\u914D\u6240\u9009\u573A\u666F\uFF09\u3001\u2461\u80CC\u666F\u5360\u6BD4\uFF08\u226430%\uFF09\u3001\u2462\u80CC\u666F\u4F4D\u7F6E\u3001\u2463\u573A\u666F\u5143\u7D20\u7684\u5177\u4F53\u5448\u73B0\uFF08\u5982\u201C\u6D41\u52A8\u6E05\u6C34\u5448\u5F27\u5F62\u73AF\u7ED5\u852C\u83DC\uFF0C\u6C34\u82B1\u9AD8\u5EA62-3cm\u201D\uFF09\\n6. \u9884\u671F\u89C6\u89C9\u6548\u679C\uFF1A\u63CF\u8FF0\u7528\u6237\u770B\u5230\u56FE\u540E\u611F\u77E5\u5230\u7684\u65B0\u9C9C\u5EA6\uFF08\u5982\u201C\u4EFF\u4F5B\u521A\u4ECE\u83DC\u56ED\u91C7\u6458\u201D\uFF09\u4E0E\u54C1\u8D28\u611F\uFF08\u5982\u201C\u9AD8\u7AEF\u9910\u5385\u98DF\u6750\u7EA7\u522B\u201D\uFF09\uFF0C\u9700\u7ED3\u5408\u9876\u90E8\u6587\u6848\u3001\u989C\u8272\u6761\u53CA\u573A\u666F\u7EC6\u8282\u5C55\u5F00\\n</\u8F93\u51FA\u6A21\u5757>\\n\\n\u8BF7\u786E\u4FDD\u6BCF\u4E2A\u6A21\u5757\u7684\u63CF\u8FF0\u5177\u4F53\u3001\u53EF\u843D\u5730\uFF0C\u907F\u514D\u6A21\u7CCA\u8868\u8FF0\u3002\u73B0\u5728\u5F00\u59CB\u8BBE\u8BA1\u3002","remark":"\u852C\u83DC\u8BE6\u60C5\u98752","owner":"lx1989","upvotes":3,"downvotes":0,"upvoteDifference":3,"updatedAt":"2026-04-13T20:38:51.744Z"}')}}]);